int sh_drain_valve_hand_angle(const ShCharaBone *world_bone)
{
    int32_t point[3];
    for (int axis = 0; axis < 3; axis++) {
        int64_t sum = 0;
        for (int column = 0; column < 3; column++) {
            sum += (int64_t)world_bone->rotation[axis][column] * s_drain_hand_local[column];
        }
        point[axis] = (int32_t)(sum >> 12) + world_bone->translation[axis];
    }
    return sh_fixed_atan2(point[1] * 16 + 2867, point[2] * 16 + 52920);
}

unsigned sh_drain_valve_hand(ShDrainValve *valve, int step, int hand_angle, int relative_frame)
{
    unsigned sounds = 0;
    if (step != 7 && step != 12) { return 0; }
if (relative_frame >= 6 && relative_frame < 37)
        {
            if ((step == 7  && valve_angle_signed(valve->previous_angle - hand_angle) < 0) ||
                (step == 12 && valve_angle_signed(valve->previous_angle - hand_angle) > 0))
            {
                if (valve->sound_phase == 0)
                {
                    sounds |= SH_DRAIN_VALVE_SQUEAK;
                    valve->sound_phase++;
                }
                else if (!(valve->sound_phase & 0x1) && valve->sound_phase < 8)
                {
                    sounds |= SH_DRAIN_VALVE_CLICK;

                    if (valve->sound_phase == 2)
                    {
                        if (step == 12)
                        {
                            sounds |= SH_DRAIN_WATER_STOP;
                            valve->running = 0;
                        }
                        else if (step == 7)
                        {
                            sounds |= SH_DRAIN_WATER_START;
                            valve->running = 1;
                        }
                    }

                    valve->sound_phase++;
                }

                valve->rotation += valve_angle_signed(valve->previous_angle - hand_angle);

                if (valve->running != 0)
                {
                    valve->opening -= valve_angle_signed(valve->previous_angle - hand_angle);
                    if (valve->opening < 0)
                    {
                        valve->opening = 0;
                    }
                    if (valve->opening > 4080)
                    {
                        valve->opening = 4080;
                    }
                }
            }
            else if (valve->sound_phase & 1)
            {
                valve->sound_phase++;
            }
        }

        valve->previous_angle = hand_angle;
    return sounds;
}

uint8_t sh_drain_water_attenuation(int32_t distance, int opening)
{
    int vol;
if (distance < 4096)
        {
            vol = opening;
        }
        else
        {
            vol = distance;
            if (vol > 69632)
            {
                vol = 0;
            }
            else
            {
                vol = sh_q12_mul(opening, 4096 - valve_q12_div(vol - 4096,  65536));
            }
        }

        vol = ~(vol >> 4);
        
    return (uint8_t)vol;
}

int32_t sh_drain_water_distance(ShPathPoint player, ShPathPoint camera)
{
    return drain_magnitude3_q6((((player.vx + camera.vx) >> 1) + 41779),
                                            ((player.vy + camera.vy) >> 1),
                                            (((player.vz + camera.vz) >> 1) + 54681));
}
